files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #a0a0b0;
  --coin: #f5c542;
  --coin-dark: #d4a017;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border-radius: 16px;
  padding: 32px 24px;
  width: 100%;
  max-width: 420px;
  text-align: center;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 24px;
}

h1 {
  font-size: 1.5rem;
  letter-spacing: 0.5px;
}

.coin-area {
  display: flex;
  justify-content: center;
}

.coin {
  width: 120px;
  height: 120px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 35%, var(--coin), var(--coin-dark));
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--bg);
  box-shadow: inset 0 -4px 0 rgba(0, 0, 0, 0.2), 0 4px 12px rgba(0, 0, 0, 0.3);
  transition: transform 0.15s ease;
  user-select: none;
}

.coin.flipping {
  animation: flip 0.4s ease;
}

@keyframes flip {
  0% { transform: rotateY(0); }
  50% { transform: rotateY(180deg) scale(1.05); }
  100% { transform: rotateY(360deg); }
}

.result-text {
  font-size: 1.125rem;
  color: var(--muted);
  min-height: 1.5em;
}

.stats {
  display: flex;
  justify-content: space-around;
  gap: 8px;
  background: rgba(0, 0, 0, 0.2);
  border-radius: 12px;
  padding: 16px 8px;
}

.stat {
  display: flex;
  flex-direction: column;
  gap: 4px;
  flex: 1;
}

.stat-label {
  font-size: 0.875rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.stat-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text);
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 28px;
  border: none;
  border-radius: 10px;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease, box-shadow 0.15s ease;
  min-width: 100px;
}

.btn-primary {
  background: var(--accent);
  color: #fff;
}

.btn-primary:hover {
  background: #f05a72;
}

.btn-primary:active {
  transform: scale(0.97);
  background: #d13a52;
}

.btn-secondary {
  background: transparent;
  color: var(--text);
  border: 2px solid var(--muted);
}

.btn-secondary:hover {
  border-color: var(--text);
  background: rgba(255, 255, 255, 0.05);
}

.btn-secondary:active {
  transform: scale(0.97);
  background: rgba(255, 255, 255, 0.1);
}

.btn:focus-visible {
  outline: 3px solid var(--coin);
  outline-offset: 3px;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
    gap: 20px;
  }
  .coin {
    width: 100px;
    height: 100px;
    font-size: 2rem;
  }
  .btn {
    padding: 12px 20px;
    min-width: 80px;
  }
  .stats {
    padding: 12px 4px;
  }
  .stat-value {
    font-size: 1.25rem;
  }
}

(function () {
  'use strict';

  var headsCount = 0;
  var tailsCount = 0;
  var streak = 0;
  var lastSide = null;

  var coinEl = document.getElementById('coin');
  var coinFace = document.getElementById('coin-face');
  var resultText = document.getElementById('result-text');
  var headsEl = document.getElementById('heads-count');
  var tailsEl = document.getElementById('tails-count');
  var streakEl = document.getElementById('streak-count');
  var flipBtn = document.getElementById('flip-btn');
  var resetBtn = document.getElementById('reset-btn');

  function updateUI(side) {
    headsEl.textContent = headsCount;
    tailsEl.textContent = tailsCount;
    streakEl.textContent = streak;
    if (side) {
      coinFace.textContent = side === 'heads' ? 'H' : 'T';
      resultText.textContent = side.charAt(0).toUpperCase() + side.slice(1) + '!';
    }
  }

  function flip() {
    var side = Math.random() < 0.5 ? 'heads' : 'tails';

    if (side === 'heads') {
      headsCount++;
    } else {
      tailsCount++;
    }

    if (side === lastSide) {
      streak++;
    } else {
      streak = 1;
      lastSide = side;
    }

    coinEl.classList.remove('flipping');
    // Force reflow to restart animation
    void coinEl.offsetWidth;
    coinEl.classList.add('flipping');

    updateUI(side);
  }

  function reset() {
    headsCount = 0;
    tailsCount = 0;
    streak = 0;
    lastSide = null;
    coinFace.textContent = '?';
    resultText.textContent = 'Press Flip to start';
    updateUI(null);
  }

  flipBtn.addEventListener('click', flip);
  resetBtn.addEventListener('click', reset);

  updateUI(null);
})();
